INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 24, 'theory', 'Quiz: consistency');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 24, 0, 'What does the CAP theorem claim for a network that has split into two parts?', '["The system must stop", "You have to choose: refuse some requests for the sake of consistency, or answer, possibly with stale data, for the sake of availability", "The data synchronizes automatically", "The partition does not affect the choice"]', 1, 'Network partitions are unavoidable, so the real choice is between CP and AP; PACELC adds that even without a partition you must choose between latency and consistency.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 24, 1, 'What does linearizability guarantee?', '["All operations run on one machine", "The clocks of all nodes match", "Writes never conflict", "The system behaves as a single copy: a completed write is visible to any read that started later"]', 3, 'The guarantee is strong and intuitive, but it requires coordinating nodes, which means latency and unavailability during a partition; so it is used where who goes first matters.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 24, 2, 'How does causal consistency differ from eventual consistency?', '["Causal guarantees an effect is not visible before its cause; eventual only promises convergence over time", "It does not", "Causal works only on one node", "Eventual is stronger than causal"]', 0, 'The causal model stays available during a partition and keeps a sensible order; eventual guarantees neither order nor speed of convergence.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 24, 3, 'How do Lamport clocks work?', '["They take the time from NTP", "They add up the times of all nodes", "On receiving a message the counter becomes max(own, received) + 1: a cause always has a smaller number", "They measure network speed"]', 2, 'Logical clocks do not depend on physical clock drift and preserve the causal order of events.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 24, 4, 'How do you get an "exactly once" effect with unreliable delivery?', '["Send the message only once", "Deliver at least once, and the receiver processes idempotently by a unique operation identifier", "Turn off retries", "Use a faster network"]', 1, 'A repeat with the same id does not change the result; the outbox pattern makes sending an event atomic with the data change.');
